#include <iostream>
using namespace std;

// Retorna el més gran de a i b
int max2(int a, int b) {
    if (a > b) {
        return a;
    } else {
        return b;
    }
}

int main() {
    int x, y, z;
    cin >> x >> y >> z;
    int m = max2(max2(x, y), z);      // el màxim de tres, amb dues crides
    cout << "Maxim: " << m << endl;
    return 0;
}

#include <iostream>
using namespace std;

// Procediment: escriu una línia de n asteriscs. No retorna res.
void escriuLinia(int n) {
    for (int i = 1; i <= n; i++) {
        cout << "*";
    }
    cout << endl;
}

int main() {
    int alcada;
    cin >> alcada;
    for (int fila = 1; fila <= alcada; fila++) {
        escriuLinia(fila);            // es crida com una instrucció
    }
    return 0;
}

