#include <iostream>
using namespace std;

void intercanvia(int &a, int &b) {    // a i b són àlies de p i q
    int aux = a;
    a = b;
    b = aux;
}

int main() {
    int p, q;
    cin >> p >> q;
    intercanvia(p, q);
    cout << p << " " << q << endl;    // 8 3
    return 0;
}

#include <iostream>
using namespace std;

// dvdnt, dvsr: dades (per valor).  Q, R: resultats (per referència).
void quocientEnterResta(int dvdnt, int dvsr, int &Q, int &R) {
    Q = 0;
    R = dvdnt;
    while (R >= dvsr) {          // mentre encara hi càpiga el divisor
        R = R - dvsr;
        Q++;
    }
}

int main() {
    int a, b, q, r;
    cin >> a >> b;               // a >= 0, b > 0
    quocientEnterResta(a, b, q, r);
    cout << a << " = " << b << " * " << q << " + " << r << endl;
    return 0;
}

#include <iostream>
using namespace std;

// Nivell 3: suma de tots els divisors de X (X inclòs)
int sumaDelsDivisors(int X) {
    int SD = 0;
    for (int P = 1; P <= X; P++) {
        if (X % P == 0) {
            SD = SD + P;
        }
    }
    return SD;
}

// Nivell 2: decidir si X és perfecte
bool esPerfecte(int X) {
    return sumaDelsDivisors(X) - X == X;
}

// Nivell 1: recórrer els candidats
int main() {
    int LIMIT;
    cin >> LIMIT;
    int X = 1;
    while (X < LIMIT) {
        if (esPerfecte(X)) {
            cout << X << " ";
        }
        X++;
    }
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int signe(int x) {
    if (x < 0) {
        return -1;
    } else {
        return 1;
    }
}

int valorAbsolut(int x) {
    if (x < 0) {
        return -x;
    } else {
        return x;
    }
}

void quocientEnterResta(int dvdnt, int dvsr, int &Q, int &R) {
    Q = 0;
    R = dvdnt;
    while (R >= dvsr) {
        R = R - dvsr;
        Q++;
    }
}

int main() {
    int A, B, N;
    cin >> A >> B >> N;                    // N >= 1 decimals
    if (B == 0) {
        cout << "Divisio impossible: el divisor es zero" << endl;
    } else {
        int s = signe(A) * signe(B);       // signe del resultat
        int a = valorAbsolut(A);
        int b = valorAbsolut(B);
        int Q, R;
        quocientEnterResta(a, b, Q, R);    // part entera
        if (s < 0 && (Q != 0 || R != 0)) {
            cout << "-";
        }
        cout << Q << ".";
        for (int i = 1; i <= N; i++) {     // cada decimal
            int dividend = R * 10;
            int xifra;
            quocientEnterResta(dividend, b, xifra, R);
            cout << xifra;
        }
        cout << endl;
    }
    return 0;
}

